import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Validate any object by reading the annotations on its fields.
 *
 * Two marker annotations are provided. Both are kept at RUNTIME, which is the
 * only reason reflection can see them at all:
 *   @NotBlank -- the String field must not be null and must contain at least
 *                one non-whitespace character
 *   @Min(n)   -- the int field must be greater than or equal to n
 *
 * validate(target) walks target.getClass().getDeclaredFields() in declared
 * order and returns one message per broken rule:
 *   "<fieldName> must not be blank"
 *   "<fieldName> must be at least <n>"
 * A field with no annotation is ignored. A valid object gives an empty list.
 *
 * The moves you need:
 *   field.isAnnotationPresent(NotBlank.class)
 *   field.getAnnotation(Min.class).value()
 *   field.setAccessible(true); field.get(target)
 *
 * Example, for new SignUpForm("", "ada@example.com", 30, null):
 *   validate(form) -> [username must not be blank]
 */
// Provided -- do not edit.
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface NotBlank {
}

// Provided -- do not edit.
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Min {

    int value();
}

// Provided -- do not edit.
class SignUpForm {

    @NotBlank
    String username;

    @NotBlank
    String email;

    @Min(18)
    int age;

    String nickname;

    SignUpForm(String username, String email, int age, String nickname) {
        this.username = username;
        this.email = email;
        this.age = age;
        this.nickname = nickname;
    }
}

// Provided -- do not edit.
class RoomBooking {

    @NotBlank
    String guest;

    @Min(1)
    int nights;

    RoomBooking(String guest, int nights) {
        this.guest = guest;
        this.nights = nights;
    }
}

public class AnnotatedFieldValidator {

    public static List<String> validate(Object target) {
        List<String> problems = new ArrayList<>();
        // TODO: loop over the declared fields of target's class.
        //       For an @NotBlank field, add a message when the value is null or blank.
        //       For an @Min field, add a message when the value is below the minimum.
        return problems;
    }
