public class AnnotatedFieldValidatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String report(Object target) {
        try {
            return String.valueOf(AnnotatedFieldValidator.validate(target));
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("a fully valid form", "[]",
                report(new SignUpForm("ada", "ada@example.com", 30, "Countess")));
        check("nickname is unannotated, so null is fine", "[]",
                report(new SignUpForm("ada", "ada@example.com", 18, null)));
        check("whitespace-only username counts as blank", "[username must not be blank]",
                report(new SignUpForm("   ", "ada@example.com", 30, null)));
        check("a null String field is blank too", "[email must not be blank]",
                report(new SignUpForm("ada", null, 30, null)));
        check("age below the minimum", "[age must be at least 18]",
                report(new SignUpForm("ada", "ada@example.com", 12, null)));
        check("every broken rule, in declared-field order",
                "[username must not be blank, email must not be blank, age must be at least 18]",
                report(new SignUpForm("", "  ", 4, "x")));
        check("a different model with its own rules",
                "[guest must not be blank, nights must be at least 1]",
                report(new RoomBooking("", 0)));
        check("a valid booking", "[]", report(new RoomBooking("Bo", 1)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

