public class AnnotatedFieldValidator {

    public static List<String> validate(Object target) {
        List<String> problems = new ArrayList<>();
        if (target == null) {
            return problems;
        }
        for (Field field : target.getClass().getDeclaredFields()) {
            if (field.isSynthetic()) {
                continue;
            }
            field.setAccessible(true);
            try {
                if (field.isAnnotationPresent(NotBlank.class)) {
                    Object value = field.get(target);
                    if (value == null || value.toString().trim().isEmpty()) {
                        problems.add(field.getName() + " must not be blank");
                    }
                }
                if (field.isAnnotationPresent(Min.class)) {
                    int minimum = field.getAnnotation(Min.class).value();
                    int actual = ((Number) field.get(target)).intValue();
                    if (actual < minimum) {
                        problems.add(field.getName() + " must be at least " + minimum);
                    }
                }
            } catch (IllegalAccessException e) {
                problems.add(field.getName() + " could not be read");
            }
        }
        return problems;
    }
}
